insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('BD', 'default', 'Bangladesh reference chart of accounts (IFRS-inspired)', '{"bn":"বাংলাদেশের নমুনা হিসাবকাঠামো (আইএফআরএস-অনুপ্রাণিত)"}'::jsonb, true, 'companies', array['BD-IFRS-IS', 'BD-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in Bangladesh. The Companies Act, 1994, s. 181 requires every company to keep proper books of account of the sums received and spent, of its sales and purchases and of its assets and liabilities, and treats books that do not give a true and fair view as not proper. The Financial Reporting Act, 2015 set up the Financial Reporting Council, which adopted the IFRS Accounting Standards without modification in November 2020 for public interest entities, and the IFRS for SMEs for those that are not publicly traded; no text prescribes account numbers. This chart is original: four digits, blocked so that each range reaches one line of the statement of financial position and the statement of profit or loss below, with the accounts a Bangladeshi company actually keeps — VAT output and input accounts kept apart from the supplementary duty payable, the VAT on imported services under section 20, the net VAT and supplementary duty due to or from the National Board of Revenue after a return, the tax and duties owed to Customs at the border, VAT withheld at source, turnover tax, advance tax at import, provident fund and workers'' profit participation and welfare funds.', 'ifrs-bangladesh')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

