insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('BD', 'BD-MUSHAK-9.1', 'Value Added Tax return (form Mushak 9.1)', array['month', 'quarter']::declaration_period[], 'quarter'::declaration_period, date '2026-07-01', null, 'Value Added Tax and Supplementary Duty Act, 2012, s. 64(1) as substituted by the Finance Act, 2026 (Act No. 96 of 2026, Bangladesh Gazette of 30 June 2026), in force on 1 July 2026 — every registered or enlisted person, or person who should be, files the return within 15 days of the end of every three tax periods; a tax period is one calendar month; the filing of a return for each tax period remains allowed (the Finance Act, 2026 as summarised by PwC; the Act itself is in Bangla and its section 64 was not read word for word). The return is Form Mushak 9.1, filed on the eVAT portal for a manufacturer, service provider or trader who takes input tax credit; every other registered person (a trader without credit, a commercial importer supplying under final settlement, a trader paying VAT on actual value addition) files Form Mushak 9.1.1, which allows no credit and which this pack does not carry; the paper return is gone. The boxes are the notes of the form (parts 3 to 7 and 10), a note''s columns (a) value, (b) supplementary duty and (c) VAT being suffixes (4a, 4b, 4c) because the form puts the duty and the VAT of a supply on one line. Supplementary duty is declared in this return (s. 64(2), s. 60(2)). The 28 September 2026 draft Value Added Tax and Supplementary Duty (Amendment) Ordinance, 2026 would restore the return for each tax period within 15 days; it was not found in the Gazette on 9 October 2026, so the rule in force — quarterly — is the one modelled. Not carried: notes 5, 6 (goods on the maximum retail price, specific VAT), 11, 13, 17, 18, 21, 22, 24, 25, 26, 29, 30, 32, 38, 40, the payment parts (8 and 9, notes 41 to 64) and the Mushak 18.6 balance.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Value Added Tax and Supplementary Duty Act, 2012, s. 64(1) as substituted by the Finance Act, 2026 — within 15 days of the end of every three tax periods, so the 15th of the month after the quarter; if the 15th is a government holiday the return is due on the next working day (the proviso of s. 64(1), inserted in 2020), which the rule does not see. Government, semi-government and autonomous bodies, banks, insurers and filers of a zero return have 20 days. The net tax is paid before the return is submitted (s. 45(2)); the Finance Bill''s monthly advance of one third of the previous quarter''s tax was not enacted, so the payment falls due with the return (PwC, Finance Act, 2026). A taxable person who files monthly by option has until the last day of the following month (PwC): the deadline field holds one rule, the quarterly one that applies to everybody by default. The rule would stay the 15th for a monthly return if the draft Ordinance of 28 September 2026 were gazetted.', 'finance-act-2026', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('BD', 'BD-MUSHAK-9.1', '1a', 'base', 'Zero rated — direct export (value)', '{"bn":"শূন্য হার — প্রত্যক্ষ রপ্তানি (মূল্য)"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 1 — zero rated goods or services, direct export: the tax-exclusive value of direct exports. The VAT and supplementary duty columns are disabled.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '2a', 'base', 'Zero rated — deemed export (value)', '{"bn":"শূন্য হার — প্রকৃত রপ্তানি নয় এমন (মূল্য)"}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 2 — zero rated goods or services, deemed export: the tax-exclusive value. The VAT and supplementary duty columns are disabled.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '3a', 'base', 'Exempted goods or services (value)', '{"bn":"অব্যাহতিপ্রাপ্ত পণ্য বা সেবা (মূল্য)"}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 3 — exempted goods or services: the tax-exclusive value of VAT-exempted supplies. The VAT and supplementary duty columns are disabled.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '4a', 'base', 'Standard rated — value', '{"bn":"মানক হার — মূল্য"}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 4 — standard rated goods or services, value in column (a): the tax-exclusive value of supplies at the standard rate (15 %).', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '4b', 'tax', 'Standard rated — supplementary duty', '{"bn":"মানক হার — সম্পূরক শুল্ক"}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 4 — column (b), the supplementary duty calculated on the value of the sub-form lines (value times the rate of the duty).', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '4c', 'tax', 'Standard rated — VAT', '{"bn":"মানক হার — মূসক"}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 4 — column (c), the VAT calculated on the value of the sub-form lines.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '7a', 'base', 'Other than standard rate — value', '{"bn":"মানক হার ব্যতীত — মূল্য"}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 7 — goods or services other than at the standard rate, value in column (a): the supplies at the truncated rates of the Third Schedule.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '7c', 'tax', 'Other than standard rate — VAT', '{"bn":"মানক হার ব্যতীত — মূসক"}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 7 — column (c), the VAT at the truncated rate. The supplementary duty column (b) is not carried: no tax code of this pack puts supplementary duty on a truncated-rate supply.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '8a', 'base', 'Retail, wholesale and trade-based supply — value', '{"bn":"খুচরা, পাইকারি ও বাণিজ্যভিত্তিক সরবরাহ — মূল্য"}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 8 — retail, wholesale and trade-based supply, value in column (a).', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '8c', 'tax', 'Retail, wholesale and trade-based supply — VAT', '{"bn":"খুচরা, পাইকারি ও বাণিজ্যভিত্তিক সরবরাহ — মূসক"}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 8 — column (c), the VAT at the trader''s rate.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '9i', 'tax', 'VAT on imported services (section 20)', '{"bn":"আমদানিকৃত সেবার ওপর মূসক (ধারা ২০)"}'::jsonb, 105, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 9 — the total VAT adds the VAT of the imported services of section 20(2), as declared in the sub-form of note 15 (IVAS guide, note 9: 9c = 4c + 5c + 6c + 7c + 8c + the VAT of imported services). Not a line of the form: the pack gives that amount a box of its own so it can be summed.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '9a', 'total', 'Total sales value', '{"bn":"মোট বিক্রয়মূল্য"}'::jsonb, 110, null, array['1a', '2a', '3a', '4a', '7a', '8a']::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 9 — total sales value and total payable taxes, column (a): 9a = 1a + 2a + 3a + 4a + 5a + 6a + 7a + 8a. Notes 5 and 6 (goods on the maximum retail price, specific VAT) are not carried.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '9b', 'total', 'Total supplementary duty', '{"bn":"মোট সম্পূরক শুল্ক"}'::jsonb, 120, null, array['4b']::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 9 — column (b): 9b = 4b + 5b + 6b + 7b + 8b; only 4b is carried.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '9c', 'total', 'Total output VAT', '{"bn":"মোট উৎপাদন কর (মূসক)"}'::jsonb, 130, null, array['4c', '7c', '8c', '9i']::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 3, note 9 — column (c): 9c = 4c + 5c + 6c + 7c + 8c + the VAT of imported services under section 20(2).', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '10a', 'base', 'Zero rated — local purchase (value)', '{"bn":"শূন্য হার — স্থানীয় ক্রয় (মূল্য)"}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 10 — zero rated goods or services, local purchase: the tax-exclusive value.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '12a', 'base', 'Exempted — local purchase (value)', '{"bn":"অব্যাহতিপ্রাপ্ত — স্থানীয় ক্রয় (মূল্য)"}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 12 — exempted goods or services, local purchase: the tax-exclusive value.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '14a', 'base', 'Standard rated — local purchase (value)', '{"bn":"মানক হার — স্থানীয় ক্রয় (মূল্য)"}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 14 — standard rated goods or services, local purchase, value in column (a): the tax-exclusive value of purchases at 15 %. Read here as the value before supplementary duty.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '14b', 'tax', 'Standard rated — local purchase (VAT)', '{"bn":"মানক হার — স্থানীয় ক্রয় (মূসক)"}'::jsonb, 170, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 14 — column (b), the VAT paid on those purchases.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '15a', 'base', 'Standard rated — import (value)', '{"bn":"মানক হার — আমদানি (মূল্য)"}'::jsonb, 180, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 15 — standard rated goods or services, import, value in column (a); the sub-form of this note also carries the imported services of section 20(2).', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '15b', 'tax', 'Standard rated — import (VAT)', '{"bn":"মানক হার — আমদানি (মূসক)"}'::jsonb, 190, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 15 — column (b), the VAT paid at the border on imports and the VAT self-charged on imported services.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '16a', 'base', 'Other than standard rate — local purchase (value)', '{"bn":"মানক হার ব্যতীত — স্থানীয় ক্রয় (মূল্য)"}'::jsonb, 200, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 16 — goods or services other than at the standard rate, local purchase, value in column (a).', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '16b', 'tax', 'Other than standard rate — local purchase (VAT)', '{"bn":"মানক হার ব্যতীত — স্থানীয় ক্রয় (মূসক)"}'::jsonb, 210, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 16 — column (b), the VAT paid at the truncated rate.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '19a', 'base', 'Not admissible for credit — turnover tax units (value)', '{"bn":"রেয়াতযোগ্য নয় — টার্নওভার কর প্রদানকারী (মূল্য)"}'::jsonb, 220, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 19 — goods or services not admissible for credit, local purchase from turnover tax units: the value, with no VAT column that reaches the credit.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '20a', 'base', 'Not admissible for credit — unregistered entities (value)', '{"bn":"রেয়াতযোগ্য নয় — অনিবন্ধিত সরবরাহকারী (মূল্য)"}'::jsonb, 230, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 20 — goods or services not admissible for credit, local purchase from unregistered entities: the value, with no VAT column that reaches the credit.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '23a', 'total', 'Total purchase value', '{"bn":"মোট ক্রয়মূল্য"}'::jsonb, 240, null, array['10a', '12a', '14a', '15a', '16a', '19a', '20a']::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 23 — total input tax credit, column (a): 23a = 10a + 11a + 12a + 13a + 14a + 15a + 16a + 17a + 18a + 19a + 20a + 21a + 22a; only the notes this pack carries are summed.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '23b', 'total', 'Total input tax credit', '{"bn":"মোট উপকরণ কর রেয়াত"}'::jsonb, 250, null, array['14b', '15b', '16b']::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 4, note 23 — column (b): 23b = 14b + 15b + 16b + 17b + 18b; only 14b, 15b and 16b are carried. Section 45(1)(b) subtracts it from the output tax.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '27', 'tax', 'Increasing adjustment — any other (supplier credit notes)', '{"bn":"বৃদ্ধিকারী সমন্বয় — অন্যান্য"}'::jsonb, 260, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 5, note 27 — any other increasing adjustment: manually entered adjustments not covered by notes 24, 25 or 26. This pack puts there the VAT of a credit note a supplier issued to the taxable person, which reduces the credit taken. Notes 24 (VAT deducted at source by the supply receiver), 25 (payment not made through a banking channel) and 26 (debit note) are entered by hand on the portal and no tax code posts to them.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '28', 'total', 'Total increasing adjustments', '{"bn":"মোট বৃদ্ধিকারী সমন্বয়"}'::jsonb, 270, null, array['27']::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 5, note 28 — total increasing adjustment: 28 = 24 + 25 + 26 + 27; only 27 is carried.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '39', 'tax', 'Supplementary duty — credit notes issued', '{"bn":"সম্পূরক শুল্ক — ইস্যুকৃত ক্রেডিট নোট"}'::jsonb, 275, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 7, note 39 — supplementary duty against issuance of a credit note, entered by the taxpayer.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '31', 'tax', 'Decreasing adjustment — credit notes issued', '{"bn":"হ্রাসকারী সমন্বয় — ইস্যুকৃত ক্রেডিট নোট"}'::jsonb, 280, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 6, note 31 — issuance of a credit note: the VAT arising out of the credit notes the taxable person issued, entered by the taxpayer. Notes 29 (VAT deducted at source from the supplies delivered) and 30 (advance tax paid at import) are entered by hand and no tax code posts to them.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '33', 'total', 'Total decreasing adjustments', '{"bn":"মোট হ্রাসকারী সমন্বয়"}'::jsonb, 290, null, array['31']::text[], '{}'::text[], null, null, false, false, null, 'Form Mushak 9.1, part 6, note 33 — total decreasing adjustment: 33 = 29 + 30 + 31 + 32; only 31 is carried.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '34', 'total', 'Net payable VAT for the tax period', '{"bn":"কর মেয়াদের নীট প্রদেয় মূসক"}'::jsonb, 300, null, array['9c', '28']::text[], array['23b', '33']::text[], null, null, true, false, null, 'Form Mushak 9.1, part 7, note 34 — net payable VAT for the tax period (section 45): 34 = 9c - 23b + 28 - 33. Section 68 carries a negative figure forward for six tax periods and then refunds it; the figure is shown at zero here when negative, and box 65 carries the credit.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '65', 'total', 'Closing balance of VAT carried forward', '{"bn":"পরবর্তী মেয়াদে জের টানা মূসক"}'::jsonb, 310, null, array['23b', '33']::text[], array['9c', '28']::text[], null, null, true, false, null, 'Form Mushak 9.1, part 10, note 65 — closing balance (VAT), the credit carried into the next return when note 34 comes out negative (section 68(1)); note 52 of the next return takes it. The credit the Mushak 18.6 account holds (note 54) is not carried.', 'mushak-9-1-guide'),
  ('BD', 'BD-MUSHAK-9.1', '36', 'total', 'Net payable supplementary duty for the tax period', '{"bn":"কর মেয়াদের নীট প্রদেয় সম্পূরক শুল্ক"}'::jsonb, 320, null, array['9b']::text[], array['39']::text[], null, null, true, false, null, 'Form Mushak 9.1, part 7, note 36 — net payable supplementary duty before adjustment with the closing balance: 36 = 9b + 38 - (39 + 40). Only 9b and 39 are carried; notes 38 (debit notes) and 40 (duty paid on inputs against exports) are entered by hand. Section 64(2) and section 60(2) put the duty in the VAT return.', 'mushak-9-1-guide')
on conflict (country, report_code, box, kind) do update set
