insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('BD-IFRS-IS', 'BD', 'default', 'Statement of profit or loss', 'income_statement', 'IFRS-SME', date '2020-11-01', null, 'Financial Reporting Act, 2015 and the IFRS Accounting Standards adopted by the Financial Reporting Council in November 2020 (IFRS Foundation jurisdiction profile) — a statement of profit or loss under IAS 1, or a statement of comprehensive income under section 5 of the IFRS for SMEs. The lines are the analysis of expenses by nature that section 5 of the IFRS for SMEs allows, down to profit for the year; other comprehensive income is not booked by any account of this chart, so the statement stops at profit or loss.', 'ifrs-bangladesh'),
  ('BD-IFRS-SFP', 'BD', 'default', 'Statement of financial position', 'balance_sheet', 'IFRS-SME', date '2020-11-01', null, 'Companies Act, 1994, s. 181(2) — books of account that do not give a true and fair view of the company''s affairs are not proper books; Financial Reporting Act, 2015 and the IFRS Accounting Standards adopted by the Financial Reporting Council in November 2020 (IFRS Foundation jurisdiction profile) — a public interest entity prepares a statement of financial position under IAS 1, and an entity that is not publicly traded may use the IFRS for SMEs, section 4. There is no prescribed layout in the texts of this register: the lines below are the minimum line items of section 4 of the IFRS for SMEs, which a full-IFRS entity expands under IAS 1. Assets and liabilities are classified into current and non-current.', 'ifrs-bangladesh')
on conflict (code) do update set
