update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Value Added Tax and Supplementary Duty Act, 2012, s. 51 — every registered or enlisted person issues a tax invoice, in the manner the rules prescribe, on or before the date the tax becomes payable; s. 52 — a credit or debit note carries its serial number, date and time, the particulars of the original invoice and the effect on the VAT. The Act asks for a serial number and does not say in these sections that the sequence carries no gap, which is why the style is `sequential`. The layout of the Mushak 6.3 invoice is set by the VAT and Supplementary Duty Rules, 2016, which this register does not hold.',
  numbering_source_key          = 'vat-act-2012',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Value Added Tax and Supplementary Duty Act, 2012, s. 33(1) (as substituted by the Finance Act, 2019) — the VAT on a taxable supply becomes payable when the first of these occurs: the supply is made, the invoice is issued, the whole or part of the consideration is received, or the supply is used personally or given to others. Ekwo''s closed vocabulary expresses only a two-way earliest-of; `earliest_of_delivery_or_payment` is the nearest value, and the gap — an invoice issued ahead of both delivery and payment, which fixes the time in Bangladesh — is recorded in the README of this pack and in docs/international.md.',
  tax_point_source_key          = 'vat-act-2012',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Bangladeshi statute obliges a business to exchange a structured electronic invoice with another business in the sense Ekwo''s vocabulary gives the word: there is no Peppol authority, no published profile and no ISO 6523 scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. What the National Board of Revenue has instead is the Electronic Fiscal Device (EFD) and Sales Data Controller (SDC) programme, which it has been rolling out to some twenty sectors, and the online VAT system (eVAT) at vat.gov.bd, where the Mushak 9.1 return is filed and the tax paid. A fiscal device that reports each sale to the administration is not a peer-to-peer exchange between two businesses; Ekwo does not connect to an EFD or SDC, and the gap is recorded in this pack''s README and in docs/international.md. The extent of the deployment, sector by sector, is not in the texts this register holds.',
  einvoice_source_key           = 'mushak-9-1-guide',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'july'
 where country = 'BD';
